	text-align: left;
}

.welcome.right {
	float: right;
	width: 300px;
	max-width: 45%;
	border-radius: 50%;
	margin: 3rem 0 0 1.5rem;
}

.full-screen a {
	color: #5883aa;
}

@media screen and (max-width: 720px) {
	.welcome-message .widget-title {
		text-align: center;
	}

	.welcome.right {
		display: block;
		float: none;
		width: 60%;
		max-width: 60%;
		margin: 0 auto;
	}
